(* LMCM(VRAM 의 점을 CPU 가 S#7 로 읽는 명령).

   명령을 내리면 첫 점이 R#44 에 들어오고, TR 이 선 동안 S#7 을 읽을 때마다
   다음 점이 들어온다. 마지막 점이 들어오는 순간 CE 가 내려가고 TR 은 그 점을
   읽을 때까지 남는다(openMSX VDPCmdEngine::startLmcm·executeLmcm·resetColor): 읽고 난
   S#2 는 TR 도 CE 도 0 이다.
   줄을 마칠 때마다 SY 와 NY 가 바뀌어서, 두 번째 LMCM 이 NY 만 쓰면 다음 줄부터
   읽는다.

   기대값은 같은 명령열을 MSX2 카트리지 ROM 으로 만들어(S#2 를 읽다가 TR 이
   서면 S#7 을 읽어 RAM 에 쌓고, CE 가 내려가면 끝낸 뒤 S#2 의 TR·CE 를 한 번 더
   쌓는다) openMSX(my8250cbios)에서
   돌려 RAM 에 쌓인 점들과 물리 VRAM 128KB 를 덤프한 것이다. 같은 ROM 을 이
   에뮬레이터로 돌린 결과도 모든 모드(SCREEN 5~8)에서 같았다. *)

let failures = ref 0

let check name cond =
  if not cond then begin
    incr failures;
    Printf.eprintf "FAIL %s\n%!" name
  end

let set_reg t r v =
  Vdp.io_write t ~port:0x99 v;
  Vdp.io_write t ~port:0x99 (0x80 lor r)

let status t n =
  set_reg t 15 n;
  let v = Vdp.io_read t ~port:0x99 in
  set_reg t 15 0;
  v

type step =
  | Regs of (int * int) list  (* 레지스터 쓰기, 마지막이 R#46 *)
  | Read of (int * int) list * string  (* LMCM: 레지스터 쓰기 뒤 CE 가 내려갈 때까지 읽은 점 (openMSX) *)
  | Direct of (int * int) list * string
      (* LMCM 을 내리고 S#2 를 보지 않은 채 S#7 을 한 번 읽은 뒤 S#2 (TR·CE) *)

(* S#2 에서 TR 이 서면 S#7 을 읽고, CE 가 내려가면 끝낸다. CE 가 안 내려가면
   점이 너무 많아진 시점에 멈춘다. *)
let read_all t =
  let acc = Buffer.create 64 in
  let rec go polls =
    let s2 = status t 2 in
    if s2 land 0x80 <> 0 then Buffer.add_char acc (Char.chr (status t 7));
    if s2 land 1 <> 0 && polls < 4096 then go (polls + 1)
  in
  go 0;
  Buffer.contents acc

let hex s = String.concat "" (List.map (fun c -> Printf.sprintf "%02x" (Char.code c)) (List.of_seq (String.to_seq s)))

let run_mode (label, r0, scenarios, whole) =
  let t = Vdp.create () in
  List.iter (fun (r, v) -> set_reg t r v)
    [ (1, 0x00); (0, r0); (2, 0x1f); (7, 0); (8, 0x0a); (9, 0x80) ];
  List.iter (fun (r, v) -> set_reg t r v)
    [ (32, 0); (33, 0); (34, 0); (35, 0); (36, 0); (37, 0); (38, 0); (39, 0);
      (40, 0); (41, 0); (42, 0); (43, 0); (44, 0); (45, 0); (46, 0x80) ];
  List.iter
    (fun (name, steps) ->
      List.iter
        (function
          | Regs w -> List.iter (fun (r, v) -> set_reg t r v) w
          | Read (w, expected) ->
            List.iter (fun (r, v) -> set_reg t r v) w;
            let points = hex (read_all t) in
            let got = points ^ Printf.sprintf "%02x" (status t 2 land 0x81) in
            check (Printf.sprintf "%s %s: read %s, openMSX %s" label name got expected)
              (got = expected)
          | Direct (w, expected) ->
            List.iter (fun (r, v) -> set_reg t r v) w;
            let point = status t 7 in
            let got = Printf.sprintf "%02x%02x" point (status t 2 land 0x81) in
            check (Printf.sprintf "%s %s: read %s, openMSX %s" label name got expected)
              (got = expected))
        steps)
    scenarios;
  let all = Bytes.create 0x20000 in
  for a = 0 to 0x1ffff do Bytes.set all a (Char.chr (Vdp.vram_read t a)) done;
  let got = Digest.to_hex (Digest.bytes all) in
  check (Printf.sprintf "%s whole VRAM MD5 %s, openMSX %s" label got whole) (got = whole)

