(* 읽는 도중에 저장하고 복원해도 남은 점이 같다. 저장 상태의 전송 칸을
   LMMC·HMMC 와 같이 쓴다. *)
let state_round_trip () =
  let t = Vdp.create () in
  List.iter (fun (r, v) -> set_reg t r v) [ (1, 0); (0, 0x06); (9, 0x80) ];
  let issue w = List.iter (fun (r, v) -> set_reg t r v) w in
  issue [ (36, 0); (37, 0); (38, 0); (39, 0); (40, 8); (41, 0); (42, 2); (43, 0); (44, 5); (45, 0); (46, 0x80) ];
  issue [ (36, 2); (38, 0); (40, 3); (42, 1); (44, 3); (46, 0x80) ];
  issue [ (32, 0); (34, 0); (40, 8); (42, 2); (45, 0); (46, 0xa0) ];
  let first = ref [] in
  for _ = 1 to 5 do first := status t 7 :: !first done;
  let w = State_codec.writer () in
  Vdp.write_state w t;
  let t2 = Vdp.create () in
  Vdp.read_state (State_codec.reader (State_codec.finish w)) t2;
  let rest t =
    let acc = ref [] in
    let rec go polls =
      let s2 = status t 2 in
      if s2 land 0x80 <> 0 then acc := status t 7 :: !acc;
      if s2 land 1 <> 0 && polls < 64 then go (polls + 1)
    in
    go 0;
    List.rev !acc
  in
  let a = rest t and b = rest t2 in
  check "restored LMCM reads the same remaining points" (a = b && a <> []);
  check "restored LMCM ends with 16 points in all" (List.length !first + List.length a = 16)

let () =
  state_round_trip ();
  List.iter run_mode modes;
  if !failures > 0 then begin
    Printf.eprintf "vdp_lmcm_test: %d failure(s)\n%!" !failures;
    exit 1
  end
  else print_endline "vdp_lmcm_test: all pass"
